cat > /tmp/pwtest/drive4.mjs << 'EOF'
import { chromium } from 'playwright'
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } })
await page.emulateMedia({ reducedMotion: 'reduce' })
await page.goto('http://localhost:3000', { waitUntil: 'networkidle' })
await page.click('.product-card >> nth=0')
let durations = []
for (let i = 0; i < 8; i++) {
  const info = await page.evaluate(() => document.getAnimations().map(a => {
    const eff = a.effect
    const timing = eff && eff.getComputedTiming ? eff.getComputedTiming() : {}
    return { name: a.animationName, duration: timing.duration }
  }).filter(x => x.name))
  durations.push(info)
  await page.waitForTimeout(20)
}
console.log(JSON.stringify(durations.flat().filter((v,i,a)=>a.findIndex(x=>x.name===v.name)===i), null, 1))
await browser.close()
EOF
cd /tmp/pwtest && node drive4.mjs 2>&1
